const test = require('node:test');
const assert = require('node:assert/strict');
const app = require('../lib/lookup-promise.cjs');
const { promisify } = require('node:util');
test('callback method retains its receiver and errors', async () => {
  const failure=new Error('missing account');
  const client={prefix:'acct:',lookup(key,callback) {
    if(key==='missing') callback(failure); else callback(null,this.prefix+key);
  }};
  const original=client.lookup;
  assert.equal(await app.lookupPromise(client,'18'),'acct:18');
  await assert.rejects(app.lookupPromise(client,'missing'),e=>e===failure);
  assert.equal(client.lookup,original);
});
test('custom promisifier is honored before binding', async () => {
  let legacyCalls=0; const failure=new Error('custom unavailable');
  const client={prefix:'ledger:',lookup(key,callback) { legacyCalls++;callback(null,'legacy'); }};
  client.lookup[promisify.custom]=function(key) {
    assert.equal(this,client);
    return key==='offline' ? Promise.reject(failure) : Promise.resolve(this.prefix+key);
  };
  assert.equal(await app.lookupPromise(client,'47'),'ledger:47');
  await assert.rejects(app.lookupPromise(client,'offline'),e=>e===failure);
  assert.equal(legacyCalls,0);
});

